mapper.select:
SELECT * FROM situation_db_access

    WHERE situation_db_access.table_name LIKE concat("%", #{situationDbAccessReq.tableName} ,"%")


    AND operation_type LIKE concat("%", #{situationDbAccessReq.operationType} ,"%")


    AND operation_time > #{situationDbAccessReq.startTime}


    AND operation_time < #{situationDbAccessReq.endTime}

ORDER BY operation_time DESC
